import json, re
from pathlib import Path

BASE = Path(__file__).resolve().parent
AUDIT = json.loads((BASE.parents[2] / 'research/icar-2026-10-30/count-audit.json').read_text(encoding='utf-8-sig'))
ROWS = [r for r in AUDIT['records'] if r['count_status'] == 'included']
CHECKED = '2026-10-30'

def source(url, title, access='page_read', kind='official', notes='Undated institutional page; checked 30 October 2026.'):
    return {'url':url, 'title':title, 'kind':kind, 'access':access, 'checked_on':CHECKED, 'supports':[], 'notes':notes}

def build(n, d):
    r=ROWS[n-1]
    name=d['name']
    sources=[{'id':'s1', **source(r['source_url'], 'ICAR accredited private institutions List II — locally audited workbook', kind='regulator', notes='Workbook read in the local input audit; this profile reuses the audited row. Intake is accreditation scope, not a confirmed current seat matrix.')}]
    for i,s in enumerate(d['sources'],2): sources.append({'id':f's{i}', **s})
    sources[0]['supports']=['identity.kind','identity.state','identity.parent_university','recognition.icar_units','programmes.icar_scope_note']
    for s in sources[1:]: s['supports']=d.get('source_supports',{}).get(s['id'],['identity','overview','campus','programmes'])
    refs=[s['id'] for s in sources[1:]]
    programme=d.get('programme','B.Sc. (Hons.) Agriculture')
    fees={'amount_inr':None,'period':None,'academic_year':None,'includes':None,'note':d.get('fee_note','A dated official fee schedule with tuition, compulsory charges and residential costs was not verified.'),'verification':'not_verified','source_ids':[]}
    if d.get('fee'): fees.update(d['fee'])
    p={'name':programme,'level':'Undergraduate','duration':d.get('duration'),'mode':d.get('mode'),'summary':d['course_summary'],'eligibility':d.get('eligibility'),'admission_route':d.get('route'),'fees':fees,'icar_scope_note':f"The audited ICAR row covers {programme} at {r['accredited_unit']} for {r['valid_from']} to {r['valid_until']}. Printed intake is retained in recognition as historical scope.",'source_ids':list(dict.fromkeys(['s1']+d.get('course_refs',refs)))}
    programmes=[p]+d.get('extra_programmes',[])
    campusrefs=d.get('campus_refs',refs)
    facilities=[{'name':x[0],'description':x[1],'source_ids':x[2] if len(x)>2 else campusrefs} for x in d.get('facilities',[])]
    gaps=[{'field':'media','reason':'Campus and logo image rights have not been acquired. Text describes a possible asset only.','next_source':d['website']}, {'field':'programmes.0.fees','reason':fees['note'],'next_source':d.get('admissions_url') or d['website']}, {'field':'admissions.dates','reason':'A reliable current dated admission calendar was not verified; undated or promotional open-admission banners are not treated as deadlines.','next_source':d.get('admissions_url') or d['website']}]
    if not d.get('scholarship_schemes'): gaps.append({'field':'scholarships.schemes','reason':d.get('scholarship_gap','No dated institution-specific scholarship terms and award conditions were verified.'),'next_source':d['website']})
    if not d.get('statistics'): gaps.append({'field':'placements.statistics','reason':'No dated agriculture-specific placement report with cohort, denominator and salary definitions was verified.','next_source':d['website']})
    if not d.get('people'): gaps.append({'field':'faculty.people','reason':'A current named agriculture faculty roster with roles was not verified from the sources read.','next_source':d['website']})
    if not d.get('eligibility'): gaps.append({'field':'programmes.0.eligibility','reason':'Current subject combinations, category thresholds and qualifying-examination rules need the official admission prospectus.','next_source':d.get('admissions_url') or d['website']})
    gaps += d.get('gaps',[])
    obj={'id':n,'slug':d.get('slug',re.sub(r'[^a-z0-9]+','-',name.lower()).strip('-')),'name':name,
      'identity':{'kind':'private_college' if r['count_type']=='Private college' else 'private_university','short_name':d.get('short'),'ownership':d.get('ownership',r['count_type']+' in the audited ICAR register'),'city':d.get('city'),'state':r['state'],'established':d.get('established'),'address':d.get('address'),'parent_university':r['affiliating_or_parent_university'] if r['count_type']=='Private college' else None,'website':d['website'],'admissions_url':d.get('admissions_url'),'phone':d.get('phone'),'email':d.get('email')},
      'hero':{'eyebrow':d.get('eyebrow','Agriculture education'),'title':name,'summary':d['hero'],'primary_cta':'Get admission guidance','secondary_cta':'Explore programmes'},
      'overview':{'heading':d['overview_heading'],'paragraphs':d['overview'],'highlights':[{'label':'Institution type','value':r['count_type']},{'label':'State','value':r['state']},{'label':'ICAR term ends','value':r['valid_until']}]+d.get('highlights',[]),'source_ids':['s1']+refs},
      'programmes':programmes,
      'admissions':{'heading':d.get('admission_heading','Planning an application to '+d.get('short',name)),'intro':d['admission_intro'],'eligibility_points':d.get('eligibility_points',[]),'steps':d.get('steps',[{'title':'Confirm the current prospectus','text':'Ask the admissions office for the applicable intake, subject requirements and selection rules before submitting an application.'},{'title':'Request a written cost statement','text':'Obtain tuition, compulsory charges, accommodation options and refund terms for the intended entry year.'}]),'documents':d.get('documents',[]),'dates':d.get('dates',[]),'application_fee_inr':None,'source_ids':d.get('admission_refs',refs)},
      'campus':{'heading':d['campus_heading'],'intro':d['campus_intro'],'facilities':facilities,'practical_learning':d.get('practical',[]),'source_ids':campusrefs},
      'scholarships':{'heading':'Scholarships and financial support','text':d.get('scholarships',f'A current agriculture-specific scholarship schedule for {d.get("short",name)} was not verified. Request the scheme name, funding authority, category rules, renewal conditions and net payable amount in writing before relying on a concession.'),'schemes':d.get('scholarship_schemes',[]),'source_ids':d.get('scholarship_refs',[])},
      'placements':{'heading':'Career support and outcomes','text':d['placements'],'statistics':d.get('statistics',[]),'recruiters':d.get('recruiters',[]),'source_ids':d.get('placement_refs',refs)},
      'recognition':{'heading':'Recognition and programme accreditation','text':f"The audited ICAR List II records {r['accredited_unit']} and the programme labels below from {r['valid_from']} through {r['valid_until']}. This is the scope verified on 30 October 2026; it does not extend automatically to other qualifications or guarantee renewal. "+r.get('scope_note',''),'icar_units':[{'unit':r['accredited_unit'],'programmes_as_printed':r['programmes_as_printed'],'valid_from':r['valid_from'],'valid_until':r['valid_until'],'source_url':r['source_url'],'source_range':r['source_sheet']+'!'+r['source_range']}],'other_recognitions':d.get('other_recognitions',[]),'source_ids':['s1']+d.get('recognition_refs',[])},
      'faculty':{'intro':d.get('faculty_intro','A current named agriculture teaching roster was not verified in the pages read. Request the department-wise faculty list, qualifications and teaching responsibilities from the institution.'),'people':d.get('people',[]),'source_ids':d.get('faculty_refs',[])},
      'faqs':[{'question':x[0],'answer':x[1],'source_ids':x[2]} for x in d['faqs']],
      'seo':{'title':name+' | Agriculture Courses & Admissions','description':d['seo'],'keywords':[name,d.get('short',name)+' agriculture',d.get('city',r['state'])+' agriculture admission',programme+' '+name]},
      'media':{'campus_image_url':None,'logo_url':None,'campus_alt':d['alt'],'caption':d['caption'],'rights_status':'not_acquired','source_ids':[]},'sources':sources,'verification_gaps':gaps,'editorial_status':'research_draft'}
    (BASE/f'{n:02d}-{obj["slug"]}.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    return obj

